with exploded as (select id, created_at, code from carts lateral view explode(coupon_codes) li as code) select code, max(created_at) as last_created_at, (unix_timestamp(max(created_at)) - unix_timestamp(min(created_at))) / 60 as span_minutes, count(*) filter (where code = 'VIP') as vip_rows, count_if(code = 'BUNDLE') as bundle_events from exploded group by code having count(*) filter (where code = 'VIP') > 1 order by vip_rows desc nulls first;
